preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");
@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: .8rem .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtsf-font-size로 바꿉니다. */
.rtsf {
  --rtsf-bg-fill: transparent;
  --rtsf-bg-border: 0;
  --rtsf-blur: none;
  --rtsf-bg-edge: none;
  --rtsf-bg-sheen: linear-gradient(transparent, transparent);
  --rtsf-bg-fallback: transparent;
  --rtsf-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtsf-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtsf-font-size: 15px;
  --rtsf-line-height: 1.75;
  --rtsf-para-gap: .8em;
  --rtsf-dialog-weight: 500;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtsf {
  --risu-font-family: var(--rtsf-font-body);
  --FontColorStandard: var(--rtsf-ink);
  --FontColorBold: var(--rtsf-strong, var(--rtsf-ink));
  --FontColorItalic: var(--rtsf-muted);
  --FontColorItalicBold: var(--rtsf-muted);
  --FontColorQuote1: var(--rtsf-muted);
  --FontColorQuote2: var(--rtsf-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtsf-ink);
  font-family: var(--rtsf-font-body);
  font-size: var(--rtsf-font-size);
  line-height: var(--rtsf-line-height);
  letter-spacing: var(--rtsf-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtsf, .rtsf *, .rtsf *::before, .rtsf *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtsf.rtsf { display: block; }
.rtsf ::selection { background: color-mix(in srgb, var(--rtsf-accent) 26%, transparent); color: inherit; }
.rtsf__content {
  min-width: 0;
  color: var(--rtsf-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtsf__content .chattext {
  --tw-prose-code: var(--rtsf-strong, var(--rtsf-ink));
  --tw-prose-pre-code: var(--rtsf-ink);
  --tw-prose-pre-bg: var(--rtsf-tint);
  max-width: none;
  color: var(--rtsf-ink);
  font-size: var(--rtsf-font-size) !important;
  line-height: var(--rtsf-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtsf__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtsf-font-size);
  line-height: var(--rtsf-line-height);
}
.rtsf__content :where(p) { margin: 0 0 var(--rtsf-para-gap); }
.rtsf__content :where(p:last-child) { margin-bottom: 0; }
.rtsf__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtsf-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtsf-strong, var(--rtsf-ink));
  font-family: var(--rtsf-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtsf__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtsf__content :where(h1) { font-size: calc(var(--rtsf-font-size) * 1.55); }
.rtsf__content :where(h2) { font-size: calc(var(--rtsf-font-size) * 1.32); }
.rtsf__content :where(h3) { font-size: calc(var(--rtsf-font-size) * 1.15); }
.rtsf__content :where(h4, h5, h6) { font-size: var(--rtsf-font-size); color: var(--rtsf-muted); }
.rtsf__content :where(strong) { font-weight: 700; color: var(--rtsf-strong, var(--rtsf-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtsf__content :where(em) { font-style: normal; color: var(--rtsf-muted); }
.rtsf__content mark[risu-mark="quote1"],
.rtsf__content mark[risu-mark="blockquote1"] { color: var(--rtsf-muted); background: transparent; }
.rtsf__content mark[risu-mark="quote2"],
.rtsf__content mark[risu-mark="blockquote2"] {
  color: var(--rtsf-dialog);
  font-weight: var(--rtsf-dialog-weight);
  background: transparent;
}
.rtsf__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtsf-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtsf-tint);
  color: var(--rtsf-muted);
}
.rtsf__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtsf__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtsf-ink); }
.rtsf__content :where(li)::marker { color: var(--rtsf-accent); }
.rtsf__content :where(a) {
  color: var(--rtsf-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtsf-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtsf__content :where(a:hover) { text-decoration-color: currentColor; }
.rtsf__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtsf-line) 15%, var(--rtsf-line) 85%, transparent);
}
.rtsf__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtsf-strong, var(--rtsf-ink));
  background: var(--rtsf-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtsf-font-size) * .88);
  line-height: 1.5;
}
.rtsf__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtsf-ink);
  background: var(--rtsf-tint);
  border: 1px solid var(--rtsf-line);
  border-radius: .5rem;
  font-size: calc(var(--rtsf-font-size) * .88);
  line-height: 1.55;
}
.rtsf__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtsf__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtsf__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtsf-ink);
  border-bottom: 1px solid var(--rtsf-line);
  text-align: left;
  vertical-align: top;
}
.rtsf__content :where(th) {
  background: var(--rtsf-tint);
  color: var(--rtsf-strong, var(--rtsf-ink));
  font-weight: 600;
}
.rtsf__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtsf__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtsf-ink) !important;
  background: var(--rtsf-edit-bg) !important;
  border: 1px solid var(--rtsf-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtsf-font-size) !important;
  line-height: var(--rtsf-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtsf__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtsf-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtsf-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtsf__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtsf-muted);
  --color-textcolor2: var(--rtsf-muted);
  --color-textcolor: var(--rtsf-ink);
  --color-darkborderc: var(--rtsf-line);
  --color-darkbutton: var(--rtsf-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtsf-muted);
}
.rtsf__info, .rtsf__actions { min-width: 0; max-width: 100%; }
.rtsf__info > div, .rtsf__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtsf-muted); }
.rtsf__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtsf__info button.transition-all,
.rtsf__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtsf__info button.transition-all:hover,
.rtsf__actions button[class*="button-icon-"]:hover { background: var(--rtsf-tint); color: var(--rtsf-ink); }
.rtsf__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtsf-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtsf__info button:not(.transition-all):hover { background: var(--rtsf-tint); color: var(--rtsf-ink); }
.rtsf :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtsf-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtsf__portrait { overflow: hidden; background: var(--rtsf-tint); }
.rtsf__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtsf, .rtsf * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtsf .rtsf__bg {
    background: var(--rtsf-bg-fallback, var(--rtsf-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtsf .rtsf__bg { background: var(--rtsf-bg-fallback, var(--rtsf-bg-fill)); }
}

.rtsf__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtsf-bg-fill);
  border: var(--rtsf-bg-border, 0);
  -webkit-backdrop-filter: var(--rtsf-blur);
  backdrop-filter: var(--rtsf-blur);
  box-shadow: var(--rtsf-bg-edge);
}

/* 구조: SF */

/* 화면 테두리(베젤): 바탕 층(__bg)에 베젤 색과 유리 흐림을 두어 글래스에서도 한 겹만 반투명해집니다. */
.rtsf {
  max-width: 54rem;
  margin: 0 auto;
  padding: clamp(5px, 1.2%, 10px);
  border-radius: clamp(.5rem, 1.6%, 1rem);
  box-shadow: 0 0 0 1px var(--rtsf-frame), 0 10px 26px rgba(0, 0, 0, .32);
}
.rtsf .rtsf__bg { background: var(--rtsf-bg-sheen), var(--rtsf-bezel); }
.rtsf__screen {
  position: relative;
  padding: 1rem clamp(1rem, 3vw, 1.65rem) .85rem;
  background:
    repeating-linear-gradient(to bottom, var(--rtsf-scan) 0, var(--rtsf-scan) 1px, transparent 1px, transparent 3px),
    var(--rtsf-panel);
  border-radius: clamp(.35rem, 1%, .65rem);
  box-shadow: inset 0 0 34px var(--rtsf-inner-glow), inset 0 0 0 1px var(--rtsf-frame);
}
.rtsf__screen::before, .rtsf__screen::after {
  content: "";
  position: absolute;
  width: clamp(10px, 2.8%, 20px);
  aspect-ratio: 1;
  border: 2px solid var(--rtsf-accent);
  opacity: .85;
  pointer-events: none;
}
.rtsf__screen::before { top: 6px; left: 6px; border-right: 0; border-bottom: 0; }
.rtsf__screen::after { bottom: 6px; right: 6px; border-left: 0; border-top: 0; }
.rtsf__bar {
  display: flex;
  align-items: center;
  gap: .55rem;
  margin-bottom: .85rem;
  padding-bottom: .55rem;
  border-bottom: 1px solid var(--rtsf-frame);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: .72em;
  letter-spacing: .12em;
  color: var(--rtsf-muted);
}
.rtsf__channel {
  display: inline-flex;
  align-items: center;
  gap: .38em;
  padding: .14em .52em;
  border-radius: .22rem;
  background: color-mix(in srgb, var(--rtsf-accent) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--rtsf-accent) 36%, transparent);
  color: var(--rtsf-accent);
  font-weight: 600;
}
.rtsf__channel::before {
  content: "";
  width: .42em;
  height: .42em;
  border-radius: 50%;
  background: var(--rtsf-accent);
  box-shadow: 0 0 6px var(--rtsf-accent);
}
.rtsf__name { color: var(--rtsf-strong, var(--rtsf-ink)); letter-spacing: .06em; font-weight: 600; }
.rtsf__signal {
  margin-left: auto;
  width: 2.2em;
  height: .55em;
  background: repeating-linear-gradient(to right, var(--rtsf-accent) 0 3px, transparent 3px 5px);
  opacity: .8;
}
.rtsf__body { display: flex; align-items: flex-start; gap: 1rem; }
.rtsf__portrait {
  position: relative;
  flex: 0 0 auto;
  width: var(--rtsf-portrait-w);
  aspect-ratio: 4 / 5;
  border-radius: .25rem;
  border: 1px solid var(--rtsf-accent);
  box-shadow: 0 0 14px var(--rtsf-inner-glow);
}
.rtsf__portrait::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(to bottom, transparent 0 2px, var(--rtsf-scan-strong) 2px 3px);
  pointer-events: none;
}
.rtsf { --rtsf-portrait-w: clamp(3.6rem, 11%, 6rem); }
.rtsf--user { --rtsf-portrait-w: clamp(2.6rem, 7%, 3.6rem); }
.rtsf--user .rtsf__body { flex-direction: row-reverse; }
.rtsf__content { flex: 1 1 auto; }
.rtsf__content :where(h1, h2, h3) { color: var(--rtsf-accent); }
.rtsf__footer { margin-top: .85rem; padding-top: .5rem; border-top: 1px solid var(--rtsf-frame); font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace; font-size: .78em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (청록) ── */
.rtsf {
  --rtsf-bezel: #0a1114;
  --rtsf-panel: #0e181d;
  --rtsf-frame: #22383e;
  --rtsf-scan: rgba(130, 200, 200, .032);
  --rtsf-scan-strong: rgba(8, 24, 26, .34);
  --rtsf-inner-glow: rgba(95, 183, 180, .11);
  --rtsf-ink: #d6e9e8;
  --rtsf-strong: #eef9f8;
  --rtsf-muted: #809c9d;
  --rtsf-accent: #6fb6b1;
  --rtsf-dialog: #a9deda;
  --rtsf-line: #22383e;
  --rtsf-tint: #13262b;
  --rtsf-edit-bg: #0b1518;
}
